          {
            command: 'pnpm --filter @cipherbox/api dev',
            url: 'http://localhost:3000/health',
            reuseExistingServer: !process.env.CI,
            timeout: 120000,
            cwd: resolve(__dirname, '../..'),
            stdout: 'pipe',
            stderr: 'pipe',
          },
          {
            command: 'pnpm --filter @cipherbox/web dev',
            url: 'http://localhost:5173',
            reuseExistingServer: !process.env.CI,
            timeout: 120000,
            cwd: resolve(__dirname, '../..'),
          },
        ],
      }),
});

